package com.cfbenchmarks.obsi.cli;

import java.nio.file.InvalidPathException;
import java.nio.file.Path;

/**
 * The command line (D-10): {@code [--new-ped] <path>}, the flag before or after the path. An unknown option, no path
 * or more than one path is a usage error. This class only reads the arguments; whether {@code --new-ped} is
 * available is decided by {@link Main}.
 */
final class CliArgs {

    static final String NEW_PED = "--new-ped";
    static final String USAGE = "usage: [--new-ped] <path>";

    sealed interface Result permits Valid, Invalid {
    }

    /** @param newPed whether {@code --new-ped} was given, once or more */
    record Valid(Path path, boolean newPed) implements Result {
    }

    /** @param reason short and stable, prefixed {@code "usage error: "} (D-08) */
    record Invalid(String reason) implements Result {
    }

    private CliArgs() {
    }

    static Result parse(String[] args) {
        Path path = null;
        int paths = 0;
        boolean newPed = false;
        for (String arg : args) {
            if (arg.equals(NEW_PED)) {
                newPed = true;
            } else if (arg.startsWith("-")) {
                // An unknown option is reported first, before the path count, so the first thing wrong is
                // what the caller reads.
                return new Invalid("usage error: unknown option " + arg);
            } else {
                paths++;
                try {
                    path = Path.of(arg);
                } catch (InvalidPathException e) {
                    // not a path this system can name (a NUL character, say): the caller's mistake, not ours
                    return new Invalid("usage error: invalid input path");
                }
            }
        }
        if (paths == 0) {
            return new Invalid("usage error: missing input path (" + USAGE + ")");
        }
        if (paths > 1) {
            return new Invalid("usage error: more than one input path (" + USAGE + ")");
        }
        return new Valid(path, newPed);
    }
}
package com.cfbenchmarks.obsi.cli;

import com.cfbenchmarks.obsi.deviation.StaticPedFilter;
import com.cfbenchmarks.obsi.input.InputParser;
import com.cfbenchmarks.obsi.input.InputResult;
import com.cfbenchmarks.obsi.input.Snapshot;
import com.cfbenchmarks.obsi.result.CalculationResult;
import com.cfbenchmarks.obsi.result.ObsiCalculator;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.util.function.Function;

/**
 * Command-line entry point: {@code [--new-ped] <path>} (D-10). A published result is one JSON object on stdout with
 * exit 0; a failure is one JSON object on stderr with a nonzero exit (docs/brief.md, "Output"). Nothing else is
 * written to either stream (D-09).
 *
 * <p>Exit codes (D-08): 0 published, 1 calculation failure (§6), 2 input or usage error, 3 unexpected internal error.
 * {@code calculationTime} is echoed on a calculation failure and is {@code null} on an input or usage error (D-07,
 * D-22).
 */
public final class Main {

    static final int EXIT_PUBLISHED = 0;
    static final int EXIT_CALCULATION_FAILED = 1;
    static final int EXIT_INPUT_OR_USAGE = 2;
    static final int EXIT_INTERNAL = 3;

    // D-22: Task 2 is not built yet, so the flag is recognised and refused.
    static final String NEW_PED_NOT_IMPLEMENTED = "usage error: --new-ped is not implemented yet";
    static final String STDOUT_WRITE_FAILED = "internal error: could not write the result to stdout";
    private static final int INTERNAL_REASON_LIMIT = 200;

    private static final ObjectMapper JSON = new ObjectMapper();

    private Main() {
    }

    public static void main(String[] args) {
        // D-22: UTF-8 explicitly, so exchange names come out as given whatever the platform's default encoding.
        PrintStream out = new PrintStream(System.out, true, StandardCharsets.UTF_8);
        PrintStream err = new PrintStream(System.err, true, StandardCharsets.UTF_8);
        System.exit(run(args, out, err));
    }

    /** Runs the original 5% rule (no {@code --new-ped} yet). Returns the exit code. */
    static int run(String[] args, PrintStream out, PrintStream err) {
        return run(args, out, err, snapshot -> ObsiCalculator.calculate(snapshot, new StaticPedFilter()));
    }

    /**
     * @param calculation the calculation to run on an accepted snapshot; a parameter so a test can make it throw
     */
    static int run(String[] args, PrintStream out, PrintStream err, Function<Snapshot, CalculationResult> calculation) {
        // Known once the input is accepted; a failure after that point echoes it (D-22).
        String calculationTime = null;
        try {
            // D-10: arguments first, so a usage error is reported before any file is touched.
            CliArgs.Result parsed = CliArgs.parse(args);
            if (parsed instanceof CliArgs.Invalid invalid) {
                return fail(err, null, invalid.reason(), EXIT_INPUT_OR_USAGE);
            }
            CliArgs.Valid arguments = (CliArgs.Valid) parsed;
            if (arguments.newPed()) {
                return fail(err, null, NEW_PED_NOT_IMPLEMENTED, EXIT_INPUT_OR_USAGE);
            }

            // D-06, D-07: an input error has no calculationTime to report.
            InputResult input = InputParser.parse(arguments.path());
            if (input instanceof InputResult.Rejected rejected) {
                return fail(err, null, rejected.reason(), EXIT_INPUT_OR_USAGE);
            }
            Snapshot snapshot = ((InputResult.Accepted) input).snapshot();
            calculationTime = snapshot.calculationTime();

            CalculationResult result = calculation.apply(snapshot);
            if (result instanceof CalculationResult.Failed failed) {
                return fail(err, failed.calculationTime(), failed.reason(), EXIT_CALCULATION_FAILED);
            }
            // Built completely before anything is written, so stdout never holds a partial result.
            String json = published((CalculationResult.Published) result);
            write(out, json);
            // D-22: a PrintStream never throws; a failed write only sets a flag. A result that could not be
            // written was not published, so say so (best effort on stderr) instead of exiting 0.
            if (out.checkError()) {
                return failBestEffort(err, calculationTime, STDOUT_WRITE_FAILED);
            }
            return EXIT_PUBLISHED;
        } catch (Throwable t) {
            // D-08, D-22: whatever went wrong, the caller gets the failure JSON and never a stack trace. This is
            // best effort: under a real OutOfMemoryError even printing the JSON may fail. Throwable and not just
            // Exception, so an Error is reported the same way.
            return failBestEffort(err, calculationTime, internalReason(t));
        }
    }

    /** Brief, "Output" (success): value and utilizedDepth are strings, written with toPlainString() (D-14). */
    private static String published(CalculationResult.Published p) {
        ObjectNode result = JSON.createObjectNode()
                .put("index", "OBSI")
                .put("calculationTime", p.calculationTime())
                .put("status", "published")
                .put("value", p.value().toPlainString());
        ObjectNode metadata = result.putObject("metadata");
        metadata.put("utilizedDepth", p.utilizedDepth().toPlainString());
        ArrayNode excluded = metadata.putArray("excludedExchanges");
        p.excludedExchanges().forEach(excluded::add);
        return result.toString();
    }

    /** Brief, "Output" (failure). {@code calculationTime} is null when the input itself doesn't conform (D-07). */
    private static int fail(PrintStream err, String calculationTime, String reason, int exit) {
        ObjectNode failure = JSON.createObjectNode().put("index", "OBSI");
        if (calculationTime == null) {
            failure.putNull("calculationTime");
        } else {
            failure.put("calculationTime", calculationTime);
        }
        failure.put("status", "failed").put("reason", reason);
        write(err, failure.toString());
        return exit;
    }

    private static int failBestEffort(PrintStream err, String calculationTime, String reason) {
        try {
            fail(err, calculationTime, reason, EXIT_INTERNAL);
        } catch (Throwable ignored) {
            // nothing more can be done: the exit code still says what happened
        }
        return EXIT_INTERNAL;
    }

    /** D-22: {@code internal error: <SimpleName>: <message>}, on one line, at most 200 characters. */
    private static String internalReason(Throwable t) {
        String name = t.getClass().getSimpleName();
        if (name.isEmpty()) {
            name = t.getClass().getName();
        }
        String reason = "internal error: " + name + (t.getMessage() == null ? "" : ": " + t.getMessage());
        reason = reason.replaceAll("\\R", " ");
        return reason.length() > INTERNAL_REASON_LIMIT ? reason.substring(0, INTERNAL_REASON_LIMIT) : reason;
    }

    /** One JSON object on one line, ended by a single newline (not the platform's line separator). */
    private static void write(PrintStream stream, String json) {
        stream.print(json);
        stream.print('\n');
        stream.flush();
    }
}
/**
 * Command-line interface: reads one snapshot from a local JSON path (optionally with
 * {@code --new-ped}), writes a published result to stdout and a failure to stderr.
 *
 * <p>Contract: docs/brief.md, "CLI" and "Output" (not defined in obsi-methodology.md). Failure
 * handling follows spec §6 "Calculation failures" ("Do not publish an index value for a failed
 * snapshot").
 */
package com.cfbenchmarks.obsi.cli;
package com.cfbenchmarks.obsi.input;

import com.fasterxml.jackson.core.StreamReadFeature;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.cfg.JsonNodeFeature;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Reads and validates the input snapshot: shape and type only.
 *
 * <p>Spec §2, first paragraph, last sentence: "Malformed top-level input and missing required
 * top-level fields are input errors." The value rules of the same paragraph (price and size
 * strictly positive, empty sides, best bid at or above best ask) are screening, not parsing, and
 * are not applied here.
 *
 * <p>Input errors are returned as {@link InputResult.Rejected} with a short reason (D-08); nothing
 * about the input makes this class throw.
 */
public final class InputParser {

    static final String INVALID_JSON = "input error: invalid JSON";
    static final String CANNOT_READ = "input error: cannot read input file";
    static final String ROOT_NOT_OBJECT = "input error: root must be an object";
    static final String TIME_MISSING = "input error: calculationTime is missing";
    static final String TIME_INVALID =
            "input error: calculationTime must be an ISO-8601 UTC timestamp ending in Z";
    static final String BOOKS_MISSING = "input error: books is missing";
    static final String BOOKS_NOT_ARRAY = "input error: books must be an array";

    private static final ObjectMapper JSON = JsonMapper.builder()
            // CLAUDE.md "Numbers": 100.2 must never pass through a double.
            .enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)
            // Keep the scale as written (100.0 stays 100.0) instead of Jackson's default stripping.
            .disable(JsonNodeFeature.STRIP_TRAILING_BIGDECIMAL_ZEROES)
            // D-06: "valid JSON" means the whole document, so trailing content is an error.
            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
            // D-17: a duplicate key inside one object is invalid JSON.
            .enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION)
            // D-05: NaN and Infinity stay invalid (ALLOW_NON_NUMERIC_NUMBERS is off by default).
            .build();

    private InputParser() {
    }

    /** Reads a file as UTF-8 JSON. A missing or unreadable file is an input error (D-10). */
    public static InputResult parse(Path file) {
        byte[] bytes;
        try {
            bytes = Files.readAllBytes(file);
        } catch (IOException | SecurityException e) {
            return reject(CANNOT_READ);
        }
        return parse(bytes);
    }

    /** Parses the UTF-8 bytes of an input document. */
    public static InputResult parse(byte[] json) {
        JsonNode root;
        try {
            root = JSON.readTree(json);
        } catch (IOException e) {
            return reject(INVALID_JSON);
        }
        // An empty or blank document yields a missing node: not valid JSON.
        if (root == null || root.isMissingNode()) {
            return reject(INVALID_JSON);
        }

        // D-06: the root must be an object.
        if (!root.isObject()) {
            return reject(ROOT_NOT_OBJECT);
        }

        // D-07: calculationTime is required; it is validated but echoed unchanged.
        JsonNode time = root.get("calculationTime");
        if (time == null || time.isNull()) {
            return reject(TIME_MISSING);
        }
        if (!isUtcInstant(time)) {
            return reject(TIME_INVALID);
        }

        // D-06, D-07: books is required and must be an array (it may be empty).
        JsonNode booksNode = root.get("books");
        if (booksNode == null || booksNode.isNull()) {
            return reject(BOOKS_MISSING);
        }
        if (!booksNode.isArray()) {
            return reject(BOOKS_NOT_ARRAY);
        }

        // D-06: each element must be an object with a valid exchange name. Checked book by book in
        // order; duplicate names are checked afterwards.
        List<BookInput> books = new ArrayList<>(booksNode.size());
        for (int i = 0; i < booksNode.size(); i++) {
            JsonNode element = booksNode.get(i);
            if (!element.isObject()) {
                return reject("input error: books[" + i + "] must be an object");
            }
            JsonNode name = element.get("exchange");
            // D-03, D-16: the name must be a string that is not empty or whitespace-only.
            if (name == null || !name.isTextual() || name.textValue().isBlank()) {
                return reject("input error: books[" + i + "].exchange must be a nonempty string");
            }
            books.add(readBook(name.textValue(), element));
        }

        // D-02, D-16, D-18: duplicate names are an input error. Compared stripped and
        // case-insensitively (Locale.ROOT); strip() uses the same whitespace definition as the
        // isBlank() check above. The names themselves are never altered.
        Set<String> seen = new HashSet<>();
        for (BookInput book : books) {
            if (!seen.add(book.exchange().strip().toLowerCase(Locale.ROOT))) {
                return reject("input error: duplicate exchange name \"" + book.exchange() + "\"");
            }
        }

        return new InputResult.Accepted(new Snapshot(time.textValue(), books));
    }

    /**
     * D-03, D-06: a book with a valid name whose {@code bids} or {@code asks} is missing or not an
     * array is kept as an {@link BookInput.UnreadableBook}, so it can be excluded and reported
     * (spec §2: "Exclude a book if its structure cannot be read").
     */
    private static BookInput readBook(String exchange, JsonNode book) {
        JsonNode bids = book.get("bids");
        JsonNode asks = book.get("asks");
        if (bids == null || !bids.isArray() || asks == null || !asks.isArray()) {
            return new BookInput.UnreadableBook(exchange);
        }
        return new BookInput.ReadableBook(exchange, readLevels(bids), readLevels(asks));
    }

    /**
     * Keeps the entries that are an array of exactly two JSON numbers (spec §2: "discard a
     * price/size entry if either component is not numeric"). D-01: only JSON numbers are numeric,
     * strings are not. D-05: wrong length, null, boolean, nested array or object: discarded.
     * Whether a number is strictly positive is a §2 value rule and is not checked here.
     */
    private static List<Level> readLevels(JsonNode side) {
        List<Level> levels = new ArrayList<>(side.size());
        for (JsonNode entry : side) {
            if (entry.isArray() && entry.size() == 2 && entry.get(0).isNumber() && entry.get(1).isNumber()) {
                levels.add(new Level(entry.get(0).decimalValue(), entry.get(1).decimalValue()));
            }
        }
        return levels;
    }

    /**
     * D-07, D-15: a JSON string that {@link Instant#parse} accepts and that ends in an uppercase
     * {@code Z}. {@code Instant.parse} alone also accepts offsets and a lowercase {@code z}, which
     * are not UTC timestamps in the sense of the brief.
     */
    private static boolean isUtcInstant(JsonNode time) {
        if (!time.isTextual() || !time.textValue().endsWith("Z")) {
            return false;
        }
        try {
            Instant.parse(time.textValue());
            return true;
        } catch (DateTimeParseException e) {
            return false;
        }
    }

    private static InputResult reject(String reason) {
        return new InputResult.Rejected(reason);
    }
}
package com.cfbenchmarks.obsi.input;

import java.util.List;
import java.util.Objects;

/**
 * A parsed input snapshot.
 *
 * @param calculationTime T (spec §1), the original string, validated but never reformatted (D-07)
 * @param books           the books in input order; may be empty (D-07)
 */
public record Snapshot(String calculationTime, List<BookInput> books) {

    public Snapshot {
        Objects.requireNonNull(calculationTime, "calculationTime");
        books = List.copyOf(books);
    }
}
package com.cfbenchmarks.obsi.input;

import java.util.Objects;

/**
 * Outcome of reading the input: either a snapshot or an input error with a short reason (D-08).
 * Input errors are values, never exceptions (spec §2: malformed input is an input error).
 */
public sealed interface InputResult {

    record Accepted(Snapshot snapshot) implements InputResult {
        public Accepted {
            Objects.requireNonNull(snapshot, "snapshot");
        }
    }

    /** @param reason short, stable, prefixed {@code "input error: "} (D-08) */
    record Rejected(String reason) implements InputResult {
        public Rejected {
            Objects.requireNonNull(reason, "reason");
        }
    }
}
package com.cfbenchmarks.obsi.result;

import com.cfbenchmarks.obsi.book.ConsolidationResult;
import com.cfbenchmarks.obsi.book.Consolidator;
import com.cfbenchmarks.obsi.deviation.DeviationFilter;
import com.cfbenchmarks.obsi.index.IndexResult;
import com.cfbenchmarks.obsi.index.ObsiIndex;
import com.cfbenchmarks.obsi.input.Snapshot;
import com.cfbenchmarks.obsi.screening.Screener;
import com.cfbenchmarks.obsi.screening.ScreeningResult;

/**
 * The calculation chain for one snapshot: screens (§2), consolidation and uncrossing (§3), curves, utilized depth
 * and index value (§4, §5). A stage that fails ends the calculation (§6: no index value is published for a failed
 * snapshot) and its reason is passed through unchanged.
 *
 * <p>The deviation filter is a parameter, so the original 5% rule and the Task 2 rule use the same chain.
 */
public final class ObsiCalculator {

    private ObsiCalculator() {
    }

    public static CalculationResult calculate(Snapshot snapshot, DeviationFilter deviationFilter) {
        String time = snapshot.calculationTime();

        // §2: entry and structural screens, then the deviation screen.
        ScreeningResult screening = Screener.screen(snapshot, deviationFilter);
        if (screening instanceof ScreeningResult.Failed failed) {
            return new CalculationResult.Failed(time, failed.reason());
        }
        ScreeningResult.Screened screened = (ScreeningResult.Screened) screening;

        // §3: consolidation and uncrossing.
        ConsolidationResult consolidation = Consolidator.consolidate(screened.survivors());
        if (consolidation instanceof ConsolidationResult.Failed failed) {
            return new CalculationResult.Failed(time, failed.reason());
        }
        ConsolidationResult.Consolidated book = (ConsolidationResult.Consolidated) consolidation;

        // §4, §5: curves, utilized depth, index value.
        IndexResult index = ObsiIndex.calculate(book);
        if (index instanceof IndexResult.Failed failed) {
            return new CalculationResult.Failed(time, failed.reason());
        }
        IndexResult.Published published = (IndexResult.Published) index;
        return new CalculationResult.Published(
                time, published.value(), published.utilizedDepth(), screened.excludedExchanges());
    }
}

