package com.cfbenchmarks.obsi.result;

import com.cfbenchmarks.obsi.book.ConsolidationResult;
import com.cfbenchmarks.obsi.book.Consolidator;
import com.cfbenchmarks.obsi.deviation.DeviationFilter;
import com.cfbenchmarks.obsi.index.IndexResult;
import com.cfbenchmarks.obsi.index.ObsiIndex;
import com.cfbenchmarks.obsi.input.Snapshot;
import com.cfbenchmarks.obsi.screening.Screener;
import com.cfbenchmarks.obsi.screening.ScreeningResult;

/**
 * The calculation chain for one snapshot: screens (§2), consolidation and uncrossing (§3), curves, utilized depth
 * and index value (§4, §5). A stage that fails ends the calculation (§6: no index value is published for a failed
 * snapshot) and its reason is passed through unchanged.
 *
 * <p>The deviation filter is a parameter, so the original 5% rule and the Task 2 rule use the same chain.
 */
public final class ObsiCalculator {

    private ObsiCalculator() {
    }

    public static CalculationResult calculate(Snapshot snapshot, DeviationFilter deviationFilter) {
        String time = snapshot.calculationTime();

        // §2: entry and structural screens, then the deviation screen.
        ScreeningResult screening = Screener.screen(snapshot, deviationFilter);
        if (screening instanceof ScreeningResult.Failed failed) {
            return new CalculationResult.Failed(time, failed.reason());
        }
        ScreeningResult.Screened screened = (ScreeningResult.Screened) screening;

        // §3: consolidation and uncrossing.
        ConsolidationResult consolidation = Consolidator.consolidate(screened.survivors());
        if (consolidation instanceof ConsolidationResult.Failed failed) {
            return new CalculationResult.Failed(time, failed.reason());
        }
        ConsolidationResult.Consolidated book = (ConsolidationResult.Consolidated) consolidation;

        // §4, §5: curves, utilized depth, index value.
        IndexResult index = ObsiIndex.calculate(book);
        if (index instanceof IndexResult.Failed failed) {
            return new CalculationResult.Failed(time, failed.reason());
        }
        IndexResult.Published published = (IndexResult.Published) index;
        return new CalculationResult.Published(
                time, published.value(), published.utilizedDepth(), screened.excludedExchanges());
    }
}

package com.cfbenchmarks.obsi.deviation;

import com.cfbenchmarks.obsi.book.ValidBook;
import com.cfbenchmarks.obsi.input.Snapshot;

import java.util.List;

/**
 * The orderbook percentage deviation (PED) screen (spec §2). Nothing outside this package knows
 * which implementation is in use: {@link StaticPedFilter} is the 5% rule, and the Task 2 filter
 * is a second implementation.
 *
 * <p>The interface is not shaped around mids only. An implementation gets each structurally valid
 * book with its best bid, best ask and levels, and the whole {@link Snapshot}, so it can use
 * other books and any further input fields. It computes whatever it needs (such as the median)
 * itself.
 */
public interface DeviationFilter {

    /**
     * @param structurallyValid the books that passed the structural screens, in input order; never
     *                          unreadable, with an empty side, or crossed
     * @param snapshot          the snapshot the books came from
     * @return the books this filter excludes: a subset of {@code structurallyValid}
     */
    List<ValidBook> excluded(List<ValidBook> structurallyValid, Snapshot snapshot);
}
/**
 * The median of the top-of-book mid-prices and the percentage-deviation (PED) screen, behind the
 * {@link com.cfbenchmarks.obsi.deviation.DeviationFilter} interface. The mid itself is
 * {@link com.cfbenchmarks.obsi.book.ValidBook#mid()}.
 *
 * <p>Spec: §2 "Constituent order book screens", mid-price formula, median (mean of the middle
 * two for an even count), PED formula, and "Exclude a book only if PED &gt; 5%. A book at
 * exactly 5% passes." No reentry state or half-limit test.
 */
package com.cfbenchmarks.obsi.deviation;
package com.cfbenchmarks.obsi.deviation;

import com.cfbenchmarks.obsi.book.ValidBook;
import com.cfbenchmarks.obsi.input.Snapshot;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

/**
 * The original static deviation rule (spec §2, §7): compute the median of the structurally valid
 * mids and exclude a book only if its PED exceeds 5%. A book at exactly 5% passes. The check is made
 * independently for every snapshot, using only that snapshot's books: no reentry state and no
 * half-limit test.
 */
public final class StaticPedFilter implements DeviationFilter {

    private static final BigDecimal TWO = BigDecimal.valueOf(2);
    private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);
    /** §7: orderbook percentage deviation limit, 5%. */
    private static final BigDecimal LIMIT_PERCENT = BigDecimal.valueOf(5);

    @Override
    public List<ValidBook> excluded(List<ValidBook> structurallyValid, Snapshot snapshot) {
        if (structurallyValid.isEmpty()) {
            return List.of();
        }
        BigDecimal median = median(structurallyValid.stream().map(ValidBook::mid).toList());

        List<ValidBook> excluded = new ArrayList<>();
        for (ValidBook book : structurallyValid) {
            if (deviatesMoreThanTheLimit(book.mid(), median)) {
                excluded.add(book);
            }
        }
        return excluded;
    }

    /**
     * §2: PED = 100·|m − median| / median %, and a book is excluded only if PED &gt; 5%. Written without
     * a division (CLAUDE.md "Numbers"): |m − median|·100 &gt; 5·median. The median is a mean of positive
     * prices, so it is positive and multiplying by it keeps the direction of the inequality.
     */
    private static boolean deviatesMoreThanTheLimit(BigDecimal mid, BigDecimal median) {
        BigDecimal deviation = mid.subtract(median).abs().multiply(HUNDRED);
        BigDecimal allowed = LIMIT_PERCENT.multiply(median);
        return deviation.compareTo(allowed) > 0;   // exactly 5% (equal) passes
    }

    /**
     * §2: the median of the mids, averaging the middle two for an even number of books. Division by 2
     * is exact (D-14). Sorting uses {@code compareTo}, so 100.0 and 100 are the same price.
     */
    static BigDecimal median(List<BigDecimal> mids) {
        if (mids.isEmpty()) {
            throw new IllegalArgumentException("median of no books");
        }
        List<BigDecimal> sorted = new ArrayList<>(mids);
        sorted.sort(BigDecimal::compareTo);
        int n = sorted.size();
        if (n % 2 == 1) {
            return sorted.get(n / 2);
        }
        return sorted.get(n / 2 - 1).add(sorted.get(n / 2)).divide(TWO);
    }
}
package com.cfbenchmarks.obsi.screening;

import com.cfbenchmarks.obsi.book.ValidBook;
import com.cfbenchmarks.obsi.deviation.DeviationFilter;
import com.cfbenchmarks.obsi.input.BookInput;
import com.cfbenchmarks.obsi.input.BookInput.ReadableBook;
import com.cfbenchmarks.obsi.input.BookInput.UnreadableBook;
import com.cfbenchmarks.obsi.input.Snapshot;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;

/**
 * Applies the §2 screens to a snapshot: the entry screen and the structural screens per book, then
 * the deviation screen on the structurally valid books. Which deviation filter is used is the
 * caller's choice; this class only knows the {@link DeviationFilter} interface.
 */
public final class Screener {

    // §6 / D-08 / D-19: the reasons when no constituent book survives screening.
    static final String NO_SURVIVOR = "no constituent book survived screening";
    static final String NO_SURVIVOR_BY_PED =
            "no constituent book survived screening (every structurally valid book was excluded by PED)";

    private Screener() {
    }

    /**
     * @throws IllegalStateException if the filter returns a book it was not given. Books are matched by
     *                               identity: {@link ValidBook} is a record, so a value-equal copy is not
     *                               the book that was passed in.
     */
    public static ScreeningResult screen(Snapshot snapshot, DeviationFilter deviationFilter) {
        List<BookInput> inputs = snapshot.books();

        // Structural screens, book by book, in input order (§2). validAt[i] is the structurally valid book
        // made from inputs.get(i), or null if that book is excluded. It ties each result back to its
        // position in the input, so nothing below needs to look a book up by name.
        ValidBook[] validAt = new ValidBook[inputs.size()];
        List<ValidBook> structurallyValid = new ArrayList<>();
        for (int i = 0; i < inputs.size(); i++) {
            switch (inputs.get(i)) {
                // §2 / D-03: a book whose structure cannot be read is excluded. It stays null here, so it
                // is reported in excludedExchanges below.
                case UnreadableBook _ -> { }
                case ReadableBook readable -> {
                    validAt[i] = BookScreen.structurallyValid(readable).orElse(null);
                    if (validAt[i] != null) {
                        structurallyValid.add(validAt[i]);
                    }
                }
            }
        }

        // Deviation screen: only on the structurally valid books (§1: the median is of structurally
        // valid mids), with the snapshot for filters that need more than the books.
        List<ValidBook> given = List.copyOf(structurallyValid);
        Set<ValidBook> deviating = identitySet(given, deviationFilter.excluded(given, snapshot));

        // Walk the input once, in order: each book is a survivor or an excluded exchange (brief "Output":
        // excludedExchanges lists every screened-out exchange in input order, names as given).
        List<ValidBook> survivors = new ArrayList<>();
        List<String> excludedExchanges = new ArrayList<>();
        for (int i = 0; i < inputs.size(); i++) {
            if (validAt[i] != null && !deviating.contains(validAt[i])) {
                survivors.add(validAt[i]);
            } else {
                excludedExchanges.add(inputs.get(i).exchange());
            }
        }

        // §6: the calculation fails if no constituent book survives screening. D-12, D-19: say so when the
        // structurally valid books were all removed by the deviation screen; if none was structurally
        // valid (or there are no books), PED never ran.
        if (survivors.isEmpty()) {
            return new ScreeningResult.Failed(structurallyValid.isEmpty() ? NO_SURVIVOR : NO_SURVIVOR_BY_PED);
        }
        return new ScreeningResult.Screened(survivors, excludedExchanges);
    }

    /** The books the filter returned, as an identity set, after checking each is one of those it was given. */
    private static Set<ValidBook> identitySet(List<ValidBook> given, List<ValidBook> returned) {
        Set<ValidBook> givenSet = Collections.newSetFromMap(new IdentityHashMap<>());
        givenSet.addAll(given);
        Set<ValidBook> result = Collections.newSetFromMap(new IdentityHashMap<>());
        for (ValidBook book : returned) {
            if (!givenSet.contains(book)) {
                throw new IllegalStateException(
                        "deviation filter returned a book it was not given (matched by identity): " + book.exchange());
            }
            result.add(book);
        }
        return result;
    }
}
package com.cfbenchmarks.obsi.book;

import com.cfbenchmarks.obsi.input.Level;

import java.math.BigDecimal;
import java.util.List;
import java.util.Objects;

/**
 * A structurally valid constituent book (spec §2): both sides are non-empty after the entry
 * screen and the best bid is below the best ask. It is what the deviation screen sees and what
 * consolidation (§3) receives for the books that survive.
 *
 * @param exchange the exchange name exactly as given in the input
 * @param bids     the entries that passed the entry screen, in input order (not sorted)
 * @param asks     the entries that passed the entry screen, in input order (not sorted)
 * @param bestBid  the highest bid price, by price and not by position (D-11)
 * @param bestAsk  the lowest ask price, by price and not by position (D-11)
 */
public record ValidBook(String exchange, List<Level> bids, List<Level> asks, BigDecimal bestBid,
                        BigDecimal bestAsk) {

    public ValidBook {
        Objects.requireNonNull(exchange, "exchange");
        bids = List.copyOf(bids);
        asks = List.copyOf(asks);
        Objects.requireNonNull(bestBid, "bestBid");
        Objects.requireNonNull(bestAsk, "bestAsk");
        // §2: a book is only valid with positive prices and best bid < best ask.
        if (bestBid.signum() <= 0 || bestBid.compareTo(bestAsk) >= 0) {
            throw new IllegalArgumentException(
                    "a structurally valid book needs 0 < bestBid < bestAsk, got " + bestBid + " / " + bestAsk);
        }
    }

    private static final BigDecimal TWO = BigDecimal.valueOf(2);

    /**
     * The top-of-book mid-price m = (b_best + a_best) / 2 (spec §2, §1). Dividing by 2 always
     * terminates, so the division is exact and needs no MathContext (D-14).
     */
    public BigDecimal mid() {
        return bestBid.add(bestAsk).divide(TWO);
    }
}
