package com.cfbenchmarks.obsi.result;

import java.math.BigDecimal;
import java.util.List;
import java.util.Objects;

/**
 * Outcome of one OBSI calculation from one snapshot (spec §6): a published value or a calculation failure.
 * Input and usage errors are not here: they happen before there is a snapshot to calculate from (D-07, D-08).
 */
public sealed interface CalculationResult {

    /**
     * @param calculationTime   the input's {@code calculationTime}, exactly as given (D-07)
     * @param value             the index rounded to two decimals (§5)
     * @param utilizedDepth     v_T in XYZ, a whole number (Eq. 2)
     * @param excludedExchanges every screened-out exchange in input order, names as given (brief, "Output")
     */
    record Published(String calculationTime, BigDecimal value, BigDecimal utilizedDepth,
                     List<String> excludedExchanges) implements CalculationResult {
        public Published {
            Objects.requireNonNull(calculationTime, "calculationTime");
            Objects.requireNonNull(value, "value");
            Objects.requireNonNull(utilizedDepth, "utilizedDepth");
            excludedExchanges = List.copyOf(excludedExchanges);
        }
    }

    /**
     * @param calculationTime the input's {@code calculationTime}, exactly as given: a calculation failure happens
     *                        on a conforming input (D-07)
     * @param reason          the §6 failure reason of the stage that failed (D-08, D-19, D-20, D-21)
     */
    record Failed(String calculationTime, String reason) implements CalculationResult {
        public Failed {
            Objects.requireNonNull(calculationTime, "calculationTime");
            Objects.requireNonNull(reason, "reason");
        }
    }
}
package com.cfbenchmarks.obsi.screening;

import com.cfbenchmarks.obsi.book.ValidBook;
import com.cfbenchmarks.obsi.deviation.DeviationFilter;
import com.cfbenchmarks.obsi.input.Snapshot;
import com.cfbenchmarks.obsi.screening.ScreeningResult.Failed;
import com.cfbenchmarks.obsi.screening.ScreeningResult.Screened;

import java.util.List;

/** Shared helpers for the screener tests. */
final class ScreenerTestSupport {

    /** A deviation filter that excludes nothing, so a test sees only the entry and structural screens. */
    static final DeviationFilter NO_DEVIATION_SCREEN = (books, snapshot) -> List.of();

    static final String PLAIN_REASON = "no constituent book survived screening";
    static final String PED_REASON =
            "no constituent book survived screening (every structurally valid book was excluded by PED)";

    private ScreenerTestSupport() {
    }

    static Screened screened(ScreeningResult result) {
        if (!(result instanceof Screened s)) {
            throw new AssertionError("expected Screened but was " + result);
        }
        return s;
    }

    static String failureReason(ScreeningResult result) {
        if (!(result instanceof Failed f)) {
            throw new AssertionError("expected Failed but was " + result);
        }
        return f.reason();
    }

    static Screened screenWithoutDeviation(Snapshot snapshot) {
        return screened(Screener.screen(snapshot, NO_DEVIATION_SCREEN));
    }

