                Arguments.of("2026-10-23T00:00:00Z", false),   // gap
                Arguments.of("2026-10-26T12:00:00Z", true),
                Arguments.of("2026-10-28T00:00:00Z", false),   // gap
                Arguments.of("2026-10-31T00:00:00Z", true));
    }

    @Test
    void overlappingWindowsAreTheirUnion() {
