        Snapshot snapshot = snapshotAt("2026-10-22T12:00:00Z", "2026-10-20T00:00:00Z", "2026-10-21T00:00:00Z");

        assertThat(excluded(snapshot, tight("100.7"))).containsExactly("C");
    }

