            assertThat(excluded(filter, snapshot, shuffled)).isEqualTo(excluded(filter, snapshot, books));
            assertThat(result).allSatisfy(b -> assertThat(books.stream().anyMatch(given -> given == b)).isTrue());
        }
    }

